import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import './ClienteManagement.css';

const ProjetoList = () => {
  const [projetos, setProjetos] = useState([]);
  const { clienteId } = useParams();

  useEffect(() => {
    // Requisição para buscar os projetos de um cliente específico
    axios.get(`http://localhost:8080/clientes/${clienteId}/projetos`)
      .then(response => {
        setProjetos(response.data);
      })
      .catch(error => {
        console.error('Erro ao buscar projetos:', error);
      });
  }, [clienteId]);

  return (
    <div className="projeto-list">
      <h2>Projetos do Cliente</h2>
      <ul>
        {projetos.map(projeto => (
          <li key={projeto.id}>{projeto.nome}</li>
        ))}
      </ul>
    </div>
  );
};

export default ProjetoList;
